import json
def parse(r):
    if isinstance(r, list) and len(r)==1 and isinstance(r[0], str):
        try: return json.loads(r[0])
        except: return r
    if isinstance(r, str):
        try: return json.loads(r)
        except: return [r]
    return r

def show2(r, n=5, clen=700):
